-- Order lines: decoded flags, business measures and delivery KPIs.
-- Revenue rules come from macros/business_rules.sql (single definition).

-- Columns dropped from brz_lineitem:
--   l_comment                    free-text filler generated by TPC-H, no analytical value
--   _batch_id, _source_relation  Bronze audit metadata: lineage questions are answered in Bronze;
--                                _loaded_at is kept (used by deduplicate and as freshness marker)
-- Columns replaced (not lost):
--   l_returnflag     -> return_status + is_returned + is_received
--   l_linestatus     -> line_status

with source as (
    {{ deduplicate(ref('brz_lineitem'), partition_by=['l_orderkey', 'l_linenumber']) }}
)

select
    -- keys
    {{ dbt_utils.generate_surrogate_key(['l_orderkey', 'l_linenumber']) }}::varchar as order_line_id,
    l_orderkey::varchar                          as order_id,
    l_partkey::varchar                           as part_id,
    l_suppkey::varchar                           as supplier_id,
    -- position of the line inside the order: an ordinal, kept numeric for sorting
    l_linenumber::number(38, 0)                  as line_number,

    -- measures
    l_quantity::number(12, 2)                    as quantity,
    l_extendedprice::number(12, 2)               as extended_price,
    l_discount::number(5, 4)                     as discount_rate,
    l_tax::number(5, 4)                          as tax_rate,
    {{ net_amount('l_extendedprice', 'l_discount') }}::number(14, 2)
        as net_amount,
    (l_extendedprice - {{ net_amount('l_extendedprice', 'l_discount') }})::number(14, 2)
        as discount_amount,
    {{ gross_amount_with_tax('l_extendedprice', 'l_discount', 'l_tax') }}::number(14, 2)
        as gross_amount_with_tax,

    -- decoded status flags
    case l_returnflag
        when 'R' then 'Returned'
        when 'A' then 'Accepted'
        when 'N' then 'Not yet delivered'
    end::varchar                                 as return_status,
    l_returnflag = 'R'                           as is_returned,
    -- 'N' lines had not been received at the dataset cut-off date
    l_returnflag <> 'N'                          as is_received,
    case l_linestatus
        when 'O' then 'Open'
        when 'F' then 'Fulfilled'
    end::varchar                                 as line_status,

    -- logistics
    l_shipdate::date                             as ship_date,
    l_commitdate::date                           as commit_date,
    l_receiptdate::date                          as receipt_date,
    l_receiptdate > l_commitdate                 as is_late_delivery,
    datediff('day', l_commitdate, l_receiptdate)::number(38, 0) as delivery_delay_days,
    datediff('day', l_shipdate, l_receiptdate)::number(38, 0)   as transit_days,
    {{ clean_label('l_shipmode') }}::varchar     as ship_mode,
    {{ clean_label('l_shipinstruct') }}::varchar as ship_instruction,

    _loaded_at
from source
